    web:'<div class="phone-website"><b>luma.</b><small>TU MARCA, EN MÓVIL</small><strong>Diseño que<br>conecta.</strong><div class="phone-web-shape"></div><span>Conócenos ↗</span></div>',
    erp:'<div class="phone-agent"><strong><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.5 11.6a8.5 8.5 0 0 1-12.6 7.5L2 21l1.9-5.7a8.5 8.5 0 1 1 16.6-3.7Z"/><path d="m8.2 7.2 1.4 2.6-1 1.1c.7 1.5 1.9 2.7 3.4 3.4l1.1-1 2.6 1.4c-.3 1.8-1.3 2.5-2.8 2.1-3.3-.9-6.1-3.7-7-7-.4-1.5.3-2.5 2.3-2.6Z"/></svg>Agente Raylab</strong><small>Atención por WhatsApp</small><div class="phone-agent-message">Hola, quisiera conocer sus servicios.</div><div class="phone-agent-message phone-agent-reply">¡Hola! Cuéntame qué necesita tu negocio y te orientamos.</div><span>Información y atención en un mismo canal</span></div>', 
